/**
 * @param {number[][]} items
 * @param {number} budget
 * @return {number}
 */
var maximumSaleItems = function(items, budget) {
    const n = items.length;
    let res = 0;

    const explore = (pos, count, remaining) => {
        if (remaining < 0) return;
        if (pos === n) {
            res = Math.max(res, count);
            return;
        }

        let free = 0;

        for (let i = 0; i < n; i++) {
            if (i !== pos && items[i][0] % items[pos][0] === 0) {
                free++;
            }
        }

        const max = Math.floor(remaining / items[pos][1]);

        for (let i = max; i >= 0; i--) {
            const forFree = Math.min(i, free);
            const single = i - forFree;
            explore(
                pos + 1,
                count + forFree * 2 + single,
                remaining - i * items[pos][1]
            );
        }
    };
    explore(0, 0, budget);

    return res;
};

/** By Leetcode */
var maximumSaleItems = function (items, budget) {
    items.sort((a, b) => a[1] - b[1]);
    let mx = 0;
    for (const [factor] of items) {
        mx = Math.max(mx, factor);
    }
    const freq = new Int32Array(mx + 1);
    for (const [factor] of items) {
        freq[factor]++;
    }
    for (let i = 1; i <= mx; i++) {
        if (freq[i] > 0) {
            for (let j = i * 2; j <= mx; j += i) {
                freq[i] += freq[j];
            }
        }
    }

    const mn = items[0][1];
    let ans = 0;
    for (const [factor, price] of items) {
        if (price > mn * 2) {
            break;
        }
        const cnt = freq[factor] - 1;
        const take = Math.min(cnt, Math.floor(budget / price));
        ans += take * 2;
        budget -= take * price;
    }
    ans += Math.floor(budget / mn);
    return ans;
};
